SELECT display_id AS problemId, COUNT(IF(STATUS=-3,STATUS,NULL)) AS pe, COUNT(IF(STATUS=-2,STATUS,NULL)) AS ce, COUNT(IF(STATUS=-1,STATUS,NULL)) AS wa, COUNT(IF(STATUS=0,STATUS,NULL)) AS ac, COUNT(IF(STATUS=1,STATUS,NULL)) AS tle, COUNT(IF(STATUS=2,STATUS,NULL)) AS mle, COUNT(IF(STATUS=3,STATUS,NULL)) AS re, COUNT(IF(STATUS=4,STATUS,NULL)) AS se, COUNT(IF(STATUS=8,STATUS,NULL)) AS pa, COUNT(*) AS total FROM judge
contest_id = #{practiceContestId}
AND display_id in
#{problemId}
GROUP BY display_id


SELECT j.created_time, j.status FROM judge j WHERE j.created_time >= #{since}

    AND ((j.contest_id = #{practiceContestId} AND EXISTS (SELECT 1 FROM problem p WHERE p.id = j.problem_id AND p.author_id = #{scope.userId}))
        OR EXISTS (SELECT 1 FROM contest c WHERE c.id = j.contest_id AND c.creator_id = #{scope.userId}))
